def reject_legacy_untyped_ledger_entries(apps: Any, schema_editor: Any) -> None:
    CashLedgerEntry = apps.get_model("billing", "CashLedgerEntry")
    unsupported = CashLedgerEntry.objects.filter(kind__in=("REFUND", "DEPOSIT", "WITHDRAWAL"))
    if unsupported.exists():
        raise RuntimeError(
            "Cannot install TP-703 over legacy untyped REFUND/DEPOSIT/WITHDRAWAL ledger rows."
        )


def reject_reverse_with_tp703_records(apps: Any, schema_editor: Any) -> None:
    Refund = apps.get_model("billing", "Refund")
    CashAdjustment = apps.get_model("billing", "CashAdjustment")
    if Refund.objects.exists() or CashAdjustment.objects.exists():
        raise RuntimeError(
            "Cannot reverse billing.0004 while immutable refund or cash adjustment records exist."
        )


