REPLACE_LEDGER_INSERT_TRIGGER = """
CREATE OR REPLACE FUNCTION billing_validate_cash_ledger_entry_insert()
RETURNS trigger AS $$
DECLARE
    shift_status varchar(16);
    shift_employee_id bigint;
    available_cash bigint;
BEGIN
    SELECT status, employee_id
      INTO shift_status, shift_employee_id
      FROM billing_cashshift
     WHERE id = NEW.cash_shift_id
     FOR UPDATE;

    IF NOT FOUND OR shift_status <> 'OPEN' THEN
        RAISE EXCEPTION 'Cash ledger entries require an open shift.'
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    IF shift_employee_id <> NEW.created_by_id THEN
        RAISE EXCEPTION 'Cash ledger entry actor must own the shift.'
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;

    IF (NEW.kind = 'REFUND' AND NEW.payment_method = 'CASH')
       OR NEW.kind = 'WITHDRAWAL' THEN
        SELECT COALESCE(
                   SUM(
                       CASE
                           WHEN kind = 'PAYMENT' AND payment_method = 'CASH'
                               THEN amount_minor
                           WHEN kind = 'REFUND' AND payment_method = 'CASH'
                               THEN -amount_minor
                           WHEN kind = 'DEPOSIT' THEN amount_minor
                           WHEN kind = 'WITHDRAWAL' THEN -amount_minor
                           ELSE 0
                       END
                   ),
                   0
               )
          INTO available_cash
          FROM billing_cashledgerentry
         WHERE cash_shift_id = NEW.cash_shift_id;

        IF available_cash < NEW.amount_minor THEN
            RAISE EXCEPTION 'Outgoing cash exceeds the available shift balance.'
                USING ERRCODE = '23514',
                      CONSTRAINT = 'billing_ledger_sufficient_cash';
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;
"""

