CREATE_REFUND_GUARD_TRIGGER = """
CREATE OR REPLACE FUNCTION billing_guard_refund()
RETURNS trigger AS $$
DECLARE
    ledger_kind varchar(16);
    ledger_amount bigint;
    ledger_method varchar(16);
    ledger_actor_id bigint;
    shift_status varchar(16);
    shift_employee_id bigint;
    payment_amount bigint;
    payment_method varchar(16);
    receivable_status varchar(16);
    employee_name varchar(255);
    employee_email varchar(254);
BEGIN
    IF TG_OP = 'UPDATE' OR TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Refunds are append-only.'
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;

    SELECT refund_ledger.kind,
           refund_ledger.amount_minor,
           refund_ledger.payment_method,
           refund_ledger.created_by_id,
           shift.status,
           shift.employee_id,
           payment_ledger.amount_minor,
           payment_ledger.payment_method,
           receivable.status,
           COALESCE(
               NULLIF(BTRIM(CONCAT_WS(' ', actor.first_name, actor.last_name)), ''),
               actor.email
           ),
           actor.email
      INTO ledger_kind,
           ledger_amount,
           ledger_method,
           ledger_actor_id,
           shift_status,
           shift_employee_id,
           payment_amount,
           payment_method,
           receivable_status,
           employee_name,
           employee_email
      FROM billing_cashledgerentry AS refund_ledger
      JOIN billing_cashshift AS shift ON shift.id = refund_ledger.cash_shift_id
      JOIN accounts_user AS actor ON actor.id = refund_ledger.created_by_id
      JOIN billing_payment AS payment ON payment.id = NEW.original_payment_id
      JOIN billing_cashledgerentry AS payment_ledger
        ON payment_ledger.id = payment.ledger_entry_id
      JOIN billing_receivable AS receivable ON receivable.id = payment.receivable_id
     WHERE refund_ledger.id = NEW.ledger_entry_id;

    IF NOT FOUND
       OR ledger_kind <> 'REFUND'
       OR ledger_amount <> payment_amount
       OR ledger_method <> payment_method
       OR ledger_amount <= 0
       OR receivable_status <> 'PAID'
       OR shift_status <> 'OPEN'
       OR ledger_actor_id <> shift_employee_id
       OR NEW.reason = ''
       OR NEW.reason <> BTRIM(NEW.reason)
       OR NEW.employee_name_snapshot <> employee_name
       OR NEW.employee_email_snapshot <> employee_email THEN
        RAISE EXCEPTION 'Refund facts do not match the immutable original payment.'
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER billing_refund_append_only
BEFORE INSERT OR UPDATE OR DELETE ON billing_refund
FOR EACH ROW EXECUTE FUNCTION billing_guard_refund();
"""

